import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

void main() => runApp(const FolioApp());

class FolioApp extends StatelessWidget {
  const FolioApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Library Books',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(useMaterial3: true, fontFamily: 'Inter'),
      home: const LoginPage(),
    );
  }
}

// ---- Palette (soft, peaceful sage & cream) ----
const sageDeep = Color(0xFF7FA487);
const forest = Color(0xFF3E5C46);
const cream = Color(0xFFFBF8F1);
const sageBg = Color(0xFFEAF1E8);
const gold = Color(0xFFD3AE6E);
const ink = Color(0xFF3A3A34);
const inkSoft = Color(0xFF7C7A70);

// Screens at or above this width (laptop/desktop) get the wide layout;
// below it (phones, small tablets) get the mobile layout.
const double kWideBreakpoint = 900;

// College logo, embedded so the app has no extra asset to bundle.
const String _logoB64 = '';
final Uint8List logoBytes = base64Decode(_logoB64);

class LoginPage extends StatefulWidget {
  const LoginPage({super.key});

  @override
  State<LoginPage> createState() => _LoginPageState();
}

class _LoginPageState extends State<LoginPage> {
  final _emailCtrl = TextEditingController();
  final _passwordCtrl = TextEditingController();
  final _formKey = GlobalKey<FormState>();

  bool _remember = false;
  bool _obscure = true;
  String? _status; // 'ok' | 'error' | null

  @override
  void dispose() {
    _emailCtrl.dispose();
    _passwordCtrl.dispose();
    super.dispose();
  }

  void _submit() {
    if (!_formKey.currentState!.validate()) return;

    // Demo-only check. Replace with a real auth call in production.
    final success = _passwordCtrl.text.length >= 4;
    setState(() => _status = success ? 'ok' : 'error');

    if (success) {
      Future.delayed(const Duration(milliseconds: 600), () {
        if (!mounted) return;
        Navigator.of(context).pushReplacement(
          MaterialPageRoute(builder: (_) => const HomePage()),
        );
      });
    }
  }

  InputDecoration _decoration(String label) {
    return InputDecoration(
      labelText: label,
      filled: true,
      fillColor: const Color(0xFFFFFEFC),
      contentPadding:
          const EdgeInsets.symmetric(horizontal: 13, vertical: 13),
      border: OutlineInputBorder(
        borderRadius: BorderRadius.circular(10),
        borderSide: const BorderSide(color: Color(0xFFE2DFD2)),
      ),
      enabledBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(10),
        borderSide: const BorderSide(color: Color(0xFFE2DFD2)),
      ),
      focusedBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(10),
        borderSide: const BorderSide(color: sageDeep, width: 1.4),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [sageBg, Color(0xFFDCE9DA)],
          ),
        ),
        child: SafeArea(
          child: Center(
            child: SingleChildScrollView(
              padding: const EdgeInsets.all(24),
              child: LayoutBuilder(
                builder: (context, constraints) {
                  final wide = MediaQuery.of(context).size.width >= kWideBreakpoint;
                  return ConstrainedBox(
                    constraints: BoxConstraints(maxWidth: wide ? 880 : 460),
                    child: Container(
                      decoration: BoxDecoration(
                        color: cream,
                        borderRadius: BorderRadius.circular(22),
                        boxShadow: [
                          BoxShadow(
                            color: forest.withOpacity(.18),
                            blurRadius: 60,
                            offset: const Offset(0, 25),
                          ),
                        ],
                      ),
                      child: wide
                          ? IntrinsicHeight(
                              child: Row(
                                crossAxisAlignment: CrossAxisAlignment.stretch,
                                children: [
                                  Expanded(child: _BrandPanel()),
                                  Expanded(
                                    child: Padding(
                                      padding:
                                          const EdgeInsets.fromLTRB(40, 44, 40, 44),
                                      child: _loginFormColumn(),
                                    ),
                                  ),
                                ],
                              ),
                            )
                          : Padding(
                              padding: const EdgeInsets.fromLTRB(40, 44, 40, 44),
                              child: _loginFormColumn(),
                            ),
                    ),
                  );
                },
              ),
            ),
          ),
        ),
      ),
    );
  }

  // Shared form body — used by both the mobile card and the wide two-panel card.
  Widget _loginFormColumn() {
    return Form(
      key: _formKey,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Logo + college name
          Row(
            children: [
              ClipOval(
                child: Container(
                  width: 56,
                  height: 56,
                  color: Colors.white,
                  padding: const EdgeInsets.all(3),
                  child: Image.memory(logoBytes, fit: BoxFit.contain),
                ),
              ),
              const SizedBox(width: 14),
              const Expanded(
                child: Text(
                  'TIRUMALA ENGINEERING COLLEGE\nTechnology · Excellence · Commitment',
                  style: TextStyle(
                    fontSize: 11.5,
                    height: 1.35,
                    fontWeight: FontWeight.w600,
                    color: inkSoft,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 22),

          const Text(
            'Library Books',
            style: TextStyle(
              fontFamily: 'serif',
              fontWeight: FontWeight.w600,
              fontSize: 26,
              color: forest,
            ),
          ),
          const SizedBox(height: 6),
          const Text(
            'Sign in to view your borrowed books, renewals, and holds.',
            style: TextStyle(fontSize: 14, color: inkSoft, height: 1.4),
          ),
          const SizedBox(height: 24),

          if (_status == 'error')
            _Banner(
              text: "That email and password don't match our records.",
              bg: const Color(0xFFF6E7E2),
              fg: const Color(0xFF8A4A2C),
            ),
          if (_status == 'ok')
            _Banner(
              text: 'Signed in — redirecting to your shelf.',
              bg: const Color(0xFFE4EFE3),
              fg: forest,
            ),
          if (_status != null) const SizedBox(height: 16),

          TextFormField(
            controller: _emailCtrl,
            keyboardType: TextInputType.emailAddress,
            style: const TextStyle(color: ink, fontSize: 14.5),
            decoration: _decoration('Email'),
            validator: (v) =>
                (v == null || !v.contains('@')) ? 'Enter a valid email' : null,
          ),
          const SizedBox(height: 18),
          StatefulBuilder(
            builder: (context, setLocal) {
              return TextFormField(
                controller: _passwordCtrl,
                obscureText: _obscure,
                style: const TextStyle(color: ink, fontSize: 14.5),
                decoration: _decoration('Password').copyWith(
                  suffixIcon: IconButton(
                    icon: Icon(
                      _obscure
                          ? Icons.visibility_outlined
                          : Icons.visibility_off_outlined,
                      size: 20,
                      color: inkSoft,
                    ),
                    onPressed: () => setLocal(() => _obscure = !_obscure),
                  ),
                ),
                validator: (v) =>
                    (v == null || v.length < 4) ? 'At least 4 characters' : null,
              );
            },
          ),
          const SizedBox(height: 10),

          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              StatefulBuilder(
                builder: (context, setLocal) {
                  return Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      SizedBox(
                        height: 22,
                        width: 22,
                        child: Checkbox(
                          value: _remember,
                          activeColor: forest,
                          onChanged: (v) =>
                              setLocal(() => _remember = v ?? false),
                        ),
                      ),
                      const SizedBox(width: 7),
                      const Text('Keep me signed in',
                          style: TextStyle(fontSize: 13, color: inkSoft)),
                    ],
                  );
                },
              ),
              TextButton(
                onPressed: () {},
                style: TextButton.styleFrom(
                  padding: EdgeInsets.zero,
                  minimumSize: Size.zero,
                  tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                ),
                child: const Text('Forgot password?',
                    style: TextStyle(fontSize: 13, color: forest)),
              ),
            ],
          ),
          const SizedBox(height: 22),

          SizedBox(
            width: double.infinity,
            child: ElevatedButton(
              onPressed: _submit,
              style: ElevatedButton.styleFrom(
                backgroundColor: forest,
                foregroundColor: cream,
                padding: const EdgeInsets.symmetric(vertical: 14),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(10),
                ),
                elevation: 0,
              ),
              child: const Text('Sign in',
                  style: TextStyle(fontWeight: FontWeight.w600, fontSize: 14.5)),
            ),
          ),
          const SizedBox(height: 22),

          Center(
            child: RichText(
              text: const TextSpan(
                style: TextStyle(fontSize: 13.5, color: inkSoft),
                children: [
                  TextSpan(text: 'New here? '),
                  TextSpan(
                    text: 'Create an account',
                    style: TextStyle(color: gold, fontWeight: FontWeight.w600),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

