class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  bool _searchOpen = false;
  bool _wideMenuOpen = false; // laptop layout: menu rail hidden until tapped
  final _searchCtrl = TextEditingController();

  @override
  void dispose() {
    _searchCtrl.dispose();
    super.dispose();
  }

  void _toggleSearch() {
    setState(() {
      _searchOpen = !_searchOpen;
      if (!_searchOpen) _searchCtrl.clear();
    });
  }

  void _openMenuItem(String label) {
    Navigator.of(context).pop(); // close drawer if open
    if (_branchGated.contains(label)) {
      Navigator.of(context).push(
        MaterialPageRoute(builder: (_) => BranchSelectPage(category: label)),
      );
    } else if (label == 'Home') {
      // already home
    } else {
      Navigator.of(context).push(
        MaterialPageRoute(builder: (_) => _PlaceholderListPage(title: label)),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final wide = MediaQuery.of(context).size.width >= kWideBreakpoint;
    return wide ? _buildWide(context) : _buildNarrow(context);
  }

  // ---------- Phone layout: drawer + app bar + horizontal-scroll sections ----------
  Widget _buildNarrow(BuildContext context) {
    return Scaffold(
      backgroundColor: sageBg,
      drawer: Drawer(
        backgroundColor: cream,
        child: SafeArea(
          child: ListView(
            padding: EdgeInsets.zero,
            children: [
              Container(
                padding: const EdgeInsets.all(20),
                color: sageBg,
                child: Row(
                  children: [
                    ClipOval(
                      child: Container(
                        width: 44,
                        height: 44,
                        color: Colors.white,
                        padding: const EdgeInsets.all(3),
                        child: Image.memory(logoBytes, fit: BoxFit.contain),
                      ),
                    ),
                    const SizedBox(width: 12),
                    const Expanded(
                      child: Text(
                        'TIRUMALA ENGINEERING COLLEGE\nLibrary',
                        style: TextStyle(
                            fontSize: 12.5,
                            fontWeight: FontWeight.w700,
                            color: forest,
                            height: 1.3),
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 6),
              for (final item in _menuItems)
                ListTile(
                  leading: Icon(item.icon, color: forest, size: 21),
                  title: Text(item.label,
                      style: const TextStyle(
                          fontSize: 14, fontWeight: FontWeight.w500, color: ink)),
                  onTap: () => _openMenuItem(item.label),
                ),
            ],
          ),
        ),
      ),
      appBar: AppBar(
        backgroundColor: sageBg,
        elevation: 0,
        leading: Builder(
          builder: (context) => IconButton(
            icon: const Icon(Icons.menu, color: forest),
            onPressed: () => Scaffold.of(context).openDrawer(),
          ),
        ),
        titleSpacing: 0,
        // Search button sits in AppBar's `actions` slot — pinned to the
        // far-right edge, the standard Material placement.
        title: _searchOpen
            ? TextField(
                controller: _searchCtrl,
                autofocus: true,
                style: const TextStyle(fontSize: 14.5, color: ink),
                decoration: const InputDecoration(
                  hintText: 'Search books, authors...',
                  hintStyle: TextStyle(fontSize: 14, color: inkSoft),
                  border: InputBorder.none,
                  isDense: true,
                ),
              )
            : Row(
                children: [
                  ClipOval(
                    child: Container(
                      width: 30,
                      height: 30,
                      color: Colors.white,
                      padding: const EdgeInsets.all(2),
                      child: Image.memory(logoBytes, fit: BoxFit.contain),
                    ),
                  ),
                  const SizedBox(width: 8),
                  const Text(
                    'Library',
                    style: TextStyle(
                        fontFamily: 'serif',
                        fontWeight: FontWeight.w600,
                        fontSize: 17,
                        color: forest),
                  ),
                ],
              ),
        actions: [
          IconButton(
            icon: Icon(_searchOpen ? Icons.close : Icons.search,
                color: forest),
            onPressed: _toggleSearch,
          ),
        ],
      ),
      body: SafeArea(
        child: Column(
          children: [
            // Menu options now live only behind the hamburger/drawer above —
            // the home body starts straight into the book sections.
            Expanded(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(18, 16, 18, 20),
                children: [
                  _CatalogSection(title: 'Recommended Books', books: _recommended),
                  const SizedBox(height: 22),
                  _CatalogSection(title: 'New Arrivals', books: _newArrivals),
                  const SizedBox(height: 22),
                  _CatalogSection(title: 'Popular This Week', books: _popular),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  // ---------- Laptop/desktop layout: fixed side rail + grid sections ----------
  Widget _buildWide(BuildContext context) {
    final selected = _menuItems.indexWhere((m) => m.label == 'Home');
    return Scaffold(
      backgroundColor: sageBg,
      body: SafeArea(
        child: Row(
          children: [
            // Rail only takes up space once the menu icon has been tapped.
            if (_wideMenuOpen) ...[
              NavigationRail(
                extended: true,
                minExtendedWidth: 220,
                backgroundColor: cream,
                selectedIndex: selected < 0 ? 0 : selected,
                onDestinationSelected: (i) =>
                    _openMenuItem(_menuItems[i].label),
                leading: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 18),
                  child: Column(
                    children: [
                      ClipOval(
                        child: Container(
                          width: 44,
                          height: 44,
                          color: Colors.white,
                          padding: const EdgeInsets.all(3),
                          child: Image.memory(logoBytes, fit: BoxFit.contain),
                        ),
                      ),
                      const SizedBox(height: 8),
                      const Text('Library',
                          style: TextStyle(
                              fontFamily: 'serif',
                              fontWeight: FontWeight.w600,
                              fontSize: 15,
                              color: forest)),
                    ],
                  ),
                ),
                destinations: [
                  for (final item in _menuItems)
                    NavigationRailDestination(
                      icon: Icon(item.icon, color: forest),
                      selectedIcon: Icon(item.icon, color: forest),
                      label: Text(item.label),
                    ),
                ],
              ),
              const VerticalDivider(width: 1, color: Color(0xFFE2DFD2)),
            ],
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Padding(
                    padding: const EdgeInsets.fromLTRB(28, 22, 28, 14),
                    child: Row(
                      children: [
                        IconButton(
                          icon: const Icon(Icons.menu, color: forest),
                          onPressed: () =>
                              setState(() => _wideMenuOpen = !_wideMenuOpen),
                        ),
                        const SizedBox(width: 4),
                        const Text(
                          'Library Books',
                          style: TextStyle(
                              fontFamily: 'serif',
                              fontWeight: FontWeight.w600,
                              fontSize: 22,
                              color: forest),
                        ),
                        const Spacer(),
                        SizedBox(
                          width: 340,
                          child: Container(
                            padding: const EdgeInsets.symmetric(horizontal: 14),
                            decoration: BoxDecoration(
                              color: Colors.white,
                              borderRadius: BorderRadius.circular(12),
                              border: Border.all(color: const Color(0xFFE2DFD2)),
                            ),
                            child: Row(
                              children: [
                                const Icon(Icons.search, size: 19, color: inkSoft),
                                const SizedBox(width: 8),
                                Expanded(
                                  child: TextField(
                                    controller: _searchCtrl,
                                    decoration: const InputDecoration(
                                      hintText: 'Search books, authors...',
                                      hintStyle:
                                          TextStyle(fontSize: 14, color: inkSoft),
                                      border: InputBorder.none,
                                      isDense: true,
                                      contentPadding:
                                          EdgeInsets.symmetric(vertical: 12),
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                  Expanded(
                    child: ListView(
                      padding: const EdgeInsets.fromLTRB(28, 0, 28, 28),
                      children: [
                        _CatalogSection(
                            title: 'Recommended Books',
                            books: _recommended,
                            wide: true),
                        const SizedBox(height: 28),
                        _CatalogSection(
                            title: 'New Arrivals', books: _newArrivals, wide: true),
                        const SizedBox(height: 28),
                        _CatalogSection(
                            title: 'Popular This Week', books: _popular, wide: true),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _CatalogSection extends StatelessWidget {
  final String title;
  final List<CatalogBook> books;
  final bool wide;
  const _CatalogSection({
    required this.title,
    required this.books,
    this.wide = false,
  });

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          title,
          style: const TextStyle(
              fontFamily: 'serif',
              fontWeight: FontWeight.w600,
              fontSize: 16,
              color: forest),
        ),
        const SizedBox(height: 10),
        wide
            ? Wrap(
                spacing: 16,
                runSpacing: 18,
                children: [
                  for (final b in books) _CoverCard(book: b),
                ],
              )
            : SizedBox(
                height: 190,
                child: ListView.separated(
                  scrollDirection: Axis.horizontal,
                  itemCount: books.length,
                  separatorBuilder: (_, __) => const SizedBox(width: 12),
                  itemBuilder: (context, i) => _CoverCard(book: books[i]),
                ),
              ),
      ],
    );
  }
}

class _CoverCard extends StatelessWidget {
  final CatalogBook book;
  const _CoverCard({required this.book});

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: () => Navigator.of(context).push(
        MaterialPageRoute(builder: (_) => BookDetailPage(book: book)),
      ),
      child: SizedBox(
        width: 112,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Container(
              height: 130,
              width: 112,
              decoration: BoxDecoration(
                color: book.coverColor,
                borderRadius: BorderRadius.circular(8),
              ),
              alignment: Alignment.bottomLeft,
              padding: const EdgeInsets.all(8),
              child: const Icon(Icons.menu_book_rounded,
                  color: Colors.white70, size: 20),
            ),
            const SizedBox(height: 6),
            Text(
              book.title,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                  fontSize: 12.5, fontWeight: FontWeight.w600, color: ink),
            ),
            Text(
              book.author,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(fontSize: 11, color: inkSoft),
            ),
          ],
        ),
      ),
    );
  }
}

