// ---- Branch selector (Previous Papers / Exam Papers / Class Materials) ----

class BranchSelectPage extends StatelessWidget {
  final String category;
  const BranchSelectPage({super.key, required this.category});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: sageBg,
      appBar: AppBar(
        backgroundColor: sageBg,
        elevation: 0,
        iconTheme: const IconThemeData(color: forest),
        title: Text(category,
            style: const TextStyle(color: forest, fontWeight: FontWeight.w600)),
      ),
      body: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(18),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text('Select your branch',
                  style: const TextStyle(
                      fontFamily: 'serif',
                      fontWeight: FontWeight.w600,
                      fontSize: 18,
                      color: ink)),
              const SizedBox(height: 16),
              Expanded(
                child: GridView.count(
                  crossAxisCount: 2,
                  mainAxisSpacing: 12,
                  crossAxisSpacing: 12,
                  childAspectRatio: 1.5,
                  children: [
                    for (final b in _branches)
                      _BranchCard(
                        label: b,
                        onTap: () => Navigator.of(context).push(
                          MaterialPageRoute(
                            builder: (_) => _PlaceholderListPage(
                                title: '$category — $b'),
                          ),
                        ),
                      ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _BranchCard extends StatelessWidget {
  final String label;
  final VoidCallback onTap;
  const _BranchCard({required this.label, required this.onTap});

  @override
  Widget build(BuildContext context) {
    return InkWell(
      borderRadius: BorderRadius.circular(14),
      onTap: onTap,
      child: Container(
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: const Color(0xFFE2DFD2)),
        ),
        alignment: Alignment.center,
        child: Text(label,
            style: const TextStyle(
                fontWeight: FontWeight.w700, fontSize: 14, color: forest)),
      ),
    );
  }
}

